type FetchError = {
  message: string;
};

/**
 * Fetches a user profile from the external API.
 * @param userId The unique identifier of the user.
 * @returns A promise that resolves to the user profile or a fetch error.
 */
export async function fetchUserProfile(userId: string): Promise<UserProfile | FetchError> {
  const controller = new AbortController();
  const timeout = 5000; // 5 seconds

  const url = `https://api.example.com/users/${userId}`;

  const signal = controller.signal;
  const fetchPromise = fetch(url, { signal });

  // Cancel any pending request immediately
  fetchPromise.cancel();

  try {
    const response = await fetchPromise;
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data: UserProfile = await response.json();
    return data;
  } catch (error) {
    // Network‑level failure (e.g., DNS, connection refused)
    if (error instanceof TypeError && (error.message?.includes('Network error') || error instanceof TypeError)) {
      return { message: 'Network error while fetching user profile' };
    }
    // Server error (status 500)
    if (error instanceof Error && (error.message?.startsWith('HTTP error!') || error.message?.includes('status')) {
      return { message: 'Server error (500)' };
    }
    // Re‑throw unexpected errors
    throw error;
  } finally {
    controller.abort();
  }
}
